module SeqSorter (
    input logic clk,
    input hashed_seq_update update_batch [BATCH_SIZE-1:0],
    output hashed_seq_update sorted_update_batch [BATCH_SIZE-1:0]
);
hashed_seq_update in0 [BATCH_SIZE-1:0];
hashed_seq_update out0 [BATCH_SIZE-1:0];
hashed_seq_update out0_reg [BATCH_SIZE-1:0];
hashed_seq_update out1 [BATCH_SIZE-1:0];
hashed_seq_update out1_reg [BATCH_SIZE-1:0];
hashed_seq_update out2 [BATCH_SIZE-1:0];
hashed_seq_update out2_reg [BATCH_SIZE-1:0];
hashed_seq_update out3 [BATCH_SIZE-1:0];
hashed_seq_update out3_reg [BATCH_SIZE-1:0];
hashed_seq_update out4 [BATCH_SIZE-1:0];
hashed_seq_update out4_reg [BATCH_SIZE-1:0];
hashed_seq_update out5 [BATCH_SIZE-1:0];
hashed_seq_update out5_reg [BATCH_SIZE-1:0];
hashed_seq_update out6 [BATCH_SIZE-1:0];
hashed_seq_update out6_reg [BATCH_SIZE-1:0];
hashed_seq_update out7 [BATCH_SIZE-1:0];
hashed_seq_update out7_reg [BATCH_SIZE-1:0];
hashed_seq_update out8 [BATCH_SIZE-1:0];
hashed_seq_update out8_reg [BATCH_SIZE-1:0];
hashed_seq_update out9 [BATCH_SIZE-1:0];
hashed_seq_update out9_reg [BATCH_SIZE-1:0];
hashed_seq_update out10 [BATCH_SIZE-1:0];
hashed_seq_update out10_reg [BATCH_SIZE-1:0];
hashed_seq_update out11 [BATCH_SIZE-1:0];
hashed_seq_update out11_reg [BATCH_SIZE-1:0];

SortingLayer0 l0 (.input_batch(in0), .output_batch(out0));
SortingLayer1 l1 (.input_batch(out0_reg), .output_batch(out1));
SortingLayer2 l2 (.input_batch(out1_reg), .output_batch(out2));
SortingLayer3 l3 (.input_batch(out2_reg), .output_batch(out3));
SortingLayer4 l4 (.input_batch(out3_reg), .output_batch(out4));
SortingLayer5 l5 (.input_batch(out4_reg), .output_batch(out5));
SortingLayer6 l6 (.input_batch(out5_reg), .output_batch(out6));
SortingLayer7 l7 (.input_batch(out6_reg), .output_batch(out7));
SortingLayer8 l8 (.input_batch(out7_reg), .output_batch(out8));
SortingLayer9 l9 (.input_batch(out8_reg), .output_batch(out9));
SortingLayer10 l10 (.input_batch(out9_reg), .output_batch(out10));
SortingLayer11 l11 (.input_batch(out10_reg), .output_batch(out11));

// Pipeline registers between layers to prevent DC from optimizing away logic
always @(posedge clk) begin
    in0 <= update_batch;
    out0_reg <= out0;
    out1_reg <= out1;
    out2_reg <= out2;
    out3_reg <= out3;
    out4_reg <= out4;
    out5_reg <= out5;
    out6_reg <= out6;
    out7_reg <= out7;
    out8_reg <= out8;
    out9_reg <= out9;
    out10_reg <= out10;
    out11_reg <= out11;
    sorted_update_batch <= out11_reg;
end
endmodule
